#pragma once
#include <cstddef>
#include <vector>
#include <memory>
#include <cmath>
namespace aad {
class Var;
// One tape per thread: Tape::active() returns this thread's tape.
class Tape {
public:
    struct Mark { std::size_t pos; };
    static Tape& active();
    std::size_t size() const;          // number of recorded nodes
    void reserve(std::size_t nodes);   // after reserve(n), recording up to n nodes allocates nothing
    Mark mark() const;
    void rewind(Mark m);               // drops the nodes recorded after m
    void clear();                      // empties the tape
    void reset_adjoints();             // sets every adjoint to 0
    void propagate(const Var& output); // resets adjoints, seeds output with 1, sweeps back

    // Internal methods for recording operations
    void record_add(const Var& a, const Var& b, Var& result);
    void record_sub(const Var& a, const Var& b, Var& result);
    void record_mul(const Var& a, const Var& b, Var& result);
    void record_div(const Var& a, const Var& b, Var& result);
    void record_neg(const Var& a, Var& result);
    void record_exp(const Var& a, Var& result);
    void record_log(const Var& a, Var& result);
    void record_sqrt(const Var& a, Var& result);
    void record_pow(const Var& a, double b, Var& result);
    void record_normal_cdf(const Var& a, Var& result);
    void record_max(const Var& a, const Var& b, Var& result);

private:
    struct Node {
        enum class OpType {
            ADD, SUB, MUL, DIV, NEG, EXP, LOG, SQRT, POW, NORMAL_CDF, MAX
        };
        OpType op;
        std::size_t result_id;
        std::size_t arg1_id;
        std::size_t arg2_id;
        double arg2_val;  // for pow operations with double exponent
        double adjoint;
        Node(OpType op, std::size_t result_id, std::size_t arg1_id, std::size_t arg2_id = 0, double arg2_val = 0.0)
            : op(op), result_id(result_id), arg1_id(arg1_id), arg2_id(arg2_id), arg2_val(arg2_val), adjoint(0.0) {}
    };

    std::vector<Node> nodes_;
    std::vector<std::size_t> marks_;
    std::size_t next_id_ = 0;
    std::vector<std::size_t> var_ids_;  // maps var id to node index
    std::vector<double> adjoints_;      // maps var id to adjoint value

    friend class Var;
};
class Var {
public:
    Var(double value = 0.0);           // records a new input node
    double value() const;
    double adjoint() const;            // d(output)/d(this) after Tape::propagate
    Var& operator+=(const Var&);
    Var& operator-=(const Var&);
    Var& operator*=(const Var&);
    Var& operator/=(const Var&);

private:
    std::size_t id_;
    double value_;
    double adjoint_;
    friend class Tape;
};
Var operator+(const Var&, const Var&);
Var operator-(const Var&, const Var&);
Var operator*(const Var&, const Var&);
Var operator/(const Var&, const Var&);
Var operator-(const Var&);
Var exp(const Var&);
Var log(const Var&);
Var sqrt(const Var&);
Var pow(const Var&, double);
Var normal_cdf(const Var&);        // standard normal CDF
Var max(const Var&, const Var&);   // derivative of the larger argument; of the first at a tie
}  // namespace aad

