    nodes_.emplace_back(Node::OpType::LOG, result.id_, a.id_);
    if (result.id_ >= var_ids_.size()) {
        var_ids_.resize(result.id_ + 1, 0);
        adjoints_.resize(result.id_ + 1, 0.0);
    }
    var_ids_[result.id_] = result.id_;
}

void Tape::record_sqrt(const Var& a, Var& result) {
    nodes_.emplace_back(Node::OpType::SQRT, result.id_, a.id_);
    if (result.id_ >= var_ids_.size()) {
        var_ids_.resize(result.id_ + 1, 0);
        adjoints_.resize(result.id_ + 1, 0.0);
    }
    var_ids_[result.id_] = result.id_;
}

void Tape::record_pow(const Var& a, double b, Var& result) {
    nodes_.emplace_back(Node::OpType::POW, result.id_, a.id_, 0, b);
    if (result.id_ >= var_ids_.size()) {
        var_ids_.resize(result.id_ + 1, 0);
        adjoints_.resize(result.id_ + 1, 0.0);
    }
    var_ids_[result.id_] = result.id_;
}

void Tape::record_normal_cdf(const Var& a, Var& result) {
    nodes_.emplace_back(Node::OpType::NORMAL_CDF, result.id_, a.id_);
    if (result.id_ >= var_ids_.size()) {
        var_ids_.resize(result.id_ + 1, 0);
        adjoints_.resize(result.id_ + 1, 0.0);
    }
    var_ids_[result.id_] = result.id_;
}

void Tape::record_max(const Var& a, const Var& b, Var& result) {
    nodes_.emplace_back(Node::OpType::MAX, result.id_, a.id_, b.id_);
    if (result.id_ >= var_ids_.size()) {
        var_ids_.resize(result.id_ + 1, 0);
        adjoints_.resize(result.id_ + 1, 0.0);
    }
    var_ids_[result.id_] = result.id_;
}

Var::Var(double value) : value_(value), adjoint_(0.0) {
    id_ = Tape::active().next_id_++;
    if (id_ >= Tape::active().var_ids_.size()) {
        Tape::active().var_ids_.resize(id_ + 1, 0);
        Tape::active().adjoints_.resize(id_ + 1, 0.0);
    }
    Tape::active().var_ids_[id_] = id_;
}

double Var::value() const {
    return value_;
}

double Var::adjoint() const {
    if (id_ < Tape::active().adjoints_.size()) {
        return Tape::active().adjoints_[id_];
    }
    return 0.0;
}

Var& Var::operator+=(const Var& other) {
    *this = *this + other;
    return *this;
}

Var& Var::operator-=(const Var& other) {
    *this = *this - other;
    return *this;
}

Var& Var::operator*=(const Var& other) {
    *this = *this * other;
    return *this;
}

Var& Var::operator/=(const Var& other) {
    *this = *this / other;
    return *this;
}

Var operator+(const Var& a, const Var& b) {
    Var result(a.value_ + b.value_);
    Tape::active().record_add(a, b, result);
    return result;
}

Var operator-(const Var& a, const Var& b) {
    Var result(a.value_ - b.value_);
    Tape::active().record_sub(a, b, result);
    return result;
}

Var operator*(const Var& a, const Var& b) {
    Var result(a.value_ * b.value_);
    Tape::active().record_mul(a, b, result);
    return result;
}

Var operator/(const Var& a, const Var& b) {
    Var result(a.value_ / b.value_);
    Tape::active().record_div(a, b, result);
    return result;
}

Var operator-(const Var& a) {
    Var result(-a.value_);
    Tape::active().record_neg(a, result);
    return result;
}

Var exp(const Var& a) {
    Var result(std::exp(a.value_));
    Tape::active().record_exp(a, result);
    return result;
}

Var log(const Var& a) {
    Var result(std::log(a.value_));
    Tape::active().record_log(a, result);
    return result;
}

Var sqrt(const Var& a) {
    Var result(std::sqrt(a.value_));
    Tape::active().record_sqrt(a, result);
    return result;
}

Var pow(const Var& a, double b) {
    Var result(std::pow(a.value_, b));
    Tape::active().record_pow(a, b, result);
    return result;
}

Var normal_cdf(const Var& a) {
    // Standard normal CDF: Φ(x) = 1/2 * (1 + erf(x/sqrt(2)))
    double x = a.value_;
    double result = 0.5 * (1.0 + std::erf(x / std::sqrt(2.0)));
    Var var_result(result);
    Tape::active().record_normal_cdf(a, var_result);
    return var_result;
}

Var max(const Var& a, const Var& b) {
    double result = std::max(a.value_, b.value_);
    Var var_result(result);
    Tape::active().record_max(a, b, var_result);
    return var_result;
}
