#include "aad.hpp"
#include <stdexcept>
#include <algorithm>
#include <cmath>
#include <numeric>
namespace aad {
// Static tape instance for each thread
thread_local Tape g_tape;

Tape& Tape::active() {
    return g_tape;
}

std::size_t Tape::size() const {
    return nodes_.size();
}

void Tape::reserve(std::size_t nodes) {
    nodes_.reserve(nodes);
}

Tape::Mark Tape::mark() const {
    return {nodes_.size()};
}

void Tape::rewind(Mark m) {
    nodes_.resize(m.pos);
    // Clear adjoints for variables that are no longer in the computation graph
    // This is a simplified approach - in a real implementation we'd track which variables are still active
}

void Tape::clear() {
    nodes_.clear();
    marks_.clear();
    next_id_ = 0;
    var_ids_.clear();
    adjoints_.clear();
}

void Tape::reset_adjoints() {
    std::fill(adjoints_.begin(), adjoints_.end(), 0.0);
}

void Tape::propagate(const Var& output) {
    // Reset adjoints
    reset_adjoints();

    // Seed the output adjoint with 1.0
    if (output.id_ < adjoints_.size()) {
        adjoints_[output.id_] = 1.0;
    }

    // Backward pass - process nodes in reverse order
    for (auto it = nodes_.rbegin(); it != nodes_.rend(); ++it) {
        const Node& node = *it;
        double adjoint = adjoints_[node.result_id];

        switch (node.op) {
            case Node::OpType::ADD:
                if (node.arg1_id < adjoints_.size()) adjoints_[node.arg1_id] += adjoint;
                if (node.arg2_id < adjoints_.size()) adjoints_[node.arg2_id] += adjoint;
                break;
            case Node::OpType::SUB:
                if (node.arg1_id < adjoints_.size()) adjoints_[node.arg1_id] += adjoint;
                if (node.arg2_id < adjoints_.size()) adjoints_[node.arg2_id] -= adjoint;
                break;
            case Node::OpType::MUL:
                if (node.arg1_id < adjoints_.size()) adjoints_[node.arg1_id] += adjoint * var_ids_[node.arg2_id];
                if (node.arg2_id < adjoints_.size()) adjoints_[node.arg2_id] += adjoint * var_ids_[node.arg1_id];
                break;
            case Node::OpType::DIV:
                if (node.arg1_id < adjoints_.size()) adjoints_[node.arg1_id] += adjoint / var_ids_[node.arg2_id];
                if (node.arg2_id < adjoints_.size()) adjoints_[node.arg2_id] -= adjoint * var_ids_[node.arg1_id] / (var_ids_[node.arg2_id] * var_ids_[node.arg2_id]);
                break;
            case Node::OpType::NEG:
                if (node.arg1_id < adjoints_.size()) adjoints_[node.arg1_id] -= adjoint;
                break;
            case Node::OpType::EXP:
                if (node.arg1_id < adjoints_.size()) adjoints_[node.arg1_id] += adjoint * std::exp(var_ids_[node.arg1_id]);
                break;
            case Node::OpType::LOG:
                if (node.arg1_id < adjoints_.size()) adjoints_[node.arg1_id] += adjoint / var_ids_[node.arg1_id];
                break;
            case Node::OpType::SQRT:
                if (node.arg1_id < adjoints_.size()) adjoints_[node.arg1_id] += adjoint / (2.0 * std::sqrt(var_ids_[node.arg1_id]));
                break;
            case Node::OpType::POW:
                if (node.arg1_id < adjoints_.size()) {
                    double base = var_ids_[node.arg1_id];
                    double exp = node.arg2_val;
                    adjoints_[node.arg1_id] += adjoint * exp * std::pow(base, exp - 1.0);
                }
                break;
            case Node::OpType::NORMAL_CDF:
                if (node.arg1_id < adjoints_.size()) {
                    double x = var_ids_[node.arg1_id];
                    double pdf = 1.0 / std::sqrt(2.0 * M_PI) * std::exp(-0.5 * x * x);
                    adjoints_[node.arg1_id] += adjoint * pdf;
                }
                break;
            case Node::OpType::MAX:
                // For max(a,b), derivative is 1 for the larger argument, 0 for the smaller
                if (node.arg1_id < adjoints_.size() && node.arg2_id < adjoints_.size()) {
                    double a = var_ids_[node.arg1_id];
                    double b = var_ids_[node.arg2_id];
                    if (a >= b) {
                        adjoints_[node.arg1_id] += adjoint;
                    } else {
                        adjoints_[node.arg2_id] += adjoint;
                    }
                }
                break;
        }
    }
}

